referenceSolutions.javascript:
function midpointChainFloorTicket(head, k) {
  const a=head; let out=[];
  let slow=a,fast=a;while(fast&&fast.next){slow=slow.next;fast=fast.next.next;}for(let node=slow;node;node=node.next)out.push(node.val);
  return out.length?Math.min(...out):0;
}

